def _start_client_span(
    client: "sentry_sdk.client.BaseClient",
    service_id: "ServiceId",
    operation_name: str,
) -> "Union[Span, StreamedSpan, None]":
    description = "aws.%s.%s" % (service_id.hyphenize(), operation_name)

    if has_span_streaming_enabled(client.options):
        if sentry_sdk.traces.get_current_span() is None:
            return None

        # The span is made current manually so that the previous span can be
        # restored when the call returns while a streaming body keeps it open.
        return sentry_sdk.traces.start_span(
            name=description,
            active=False,
            attributes={
                "sentry.op": OP.HTTP_CLIENT,
                "sentry.origin": ORIGIN,
                SPANDATA.RPC_METHOD: f"{service_id}/{operation_name}",
            },
        )

    span = sentry_sdk.start_span(
        op=OP.HTTP_CLIENT,
        name=description,
        origin=ORIGIN,
    )
    span.set_tag("aws.service_id", service_id.hyphenize())
    span.set_tag("aws.operation_name", operation_name)
    return span


def _sentry_make_api_call(
    orig_make_api_call: "Callable[..., Any]",
    botocore_client: "BaseClient",
    operation_name: str,
    *args: "Any",
    **kwargs: "Any",
) -> "Any":
    client = sentry_sdk.get_client()
    if client.get_integration(IDENTIFIER) is None:
        return orig_make_api_call(botocore_client, operation_name, *args, **kwargs)

    span: "Union[Span, StreamedSpan, None]" = None
    with capture_internal_exceptions():
        span = _start_client_span(
            client, botocore_client.meta.service_model.service_id, operation_name
        )

    if span is None:
        return orig_make_api_call(botocore_client, operation_name, *args, **kwargs)

    scope = sentry_sdk.get_current_scope()
    token = _client_call_span.set(span)
    previous_span: "Union[Span, StreamedSpan, None]"
    if isinstance(span, StreamedSpan):
        previous_span = scope.streamed_span
        scope.streamed_span = span
    else:
        previous_span = scope.span
        scope.span = span

    try:
        try:
            result = orig_make_api_call(
                botocore_client, operation_name, *args, **kwargs
            )
        finally:
            _client_call_span.reset(token)
            if isinstance(span, StreamedSpan):
                scope.streamed_span = previous_span  # type: ignore[assignment]
            else:
                scope.span = previous_span  # type: ignore[assignment]
    except BaseException as error:
        _finish_span(span, error)
        raise

    body_instrumented = False
    with capture_internal_exceptions():
        body_instrumented = _instrument_streaming_body(span, result)

    if not body_instrumented:
        _finish_span(span)

    return result


